import{_ as e,o,a as d,b as _}from"./app.DKoEZOcr.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"附录","link":"/api/appendix/appendix"},{"text":"Release Notes","link":"/api/appendix/Release_Notes/release_notes"},{"text":"CANN 9.1.0","link":"/api/appendix/Release_Notes/CANN_9_1_0"}]},"headers":[],"relativePath":"api/appendix/Release_Notes/CANN_9_1_0.md","filePath":"api/appendix/Release_Notes/CANN_9_1_0.md","outlineHeaders":[{"level":2,"title":"新增特性","slug":"新增特性","link":"#新增特性"},{"level":3,"title":"矢量计算","slug":"矢量计算","link":"#矢量计算"},{"level":3,"title":"数据搬运","slug":"数据搬运","link":"#数据搬运"},{"level":3,"title":"标量操作","slug":"标量操作","link":"#标量操作"},{"level":3,"title":"矩阵计算","slug":"矩阵计算","link":"#矩阵计算"},{"level":3,"title":"同步控制","slug":"同步控制","link":"#同步控制"},{"level":3,"title":"系统变量","slug":"系统变量","link":"#系统变量"},{"level":3,"title":"缓存控制","slug":"缓存控制","link":"#缓存控制"},{"level":2,"title":"Bug修复","slug":"Bug修复","link":"#Bug修复"},{"level":2,"title":"增强","slug":"增强","link":"#增强"},{"level":2,"title":"接口废弃","slug":"接口废弃","link":"#接口废弃"},{"level":3,"title":"数据搬运","slug":"数据搬运-1","link":"#数据搬运-1"}],"lastUpdated":1787050286000}'),a={name:"api/appendix/Release_Notes/CANN_9_1_0.md"};function l(t,c,s,i,n,r){return o(),d("div",null,[...c[0]||(c[0]=[_('<div><article class="markdown-body"><h1>C API</h1><p>CANN 9.1.0继续完善Ascend 950PR/Ascend 950DT（3510架构）C API，新增矢量计算、数据搬运、标量操作、矩阵计算、同步控制、系统变量和缓存控制接口，并修复9.0.0中的函数命名、类型声明和地址自更新签名问题。</p><h2 id="新增特性">新增特性<a class="header-anchor" href="#新增特性">​</a></h2><h3 id="矢量计算">矢量计算<a class="header-anchor" href="#矢量计算">​</a></h3><ul><li><code>asc_bitsort</code>、<code>asc_bitsort_sync</code>：分数（Score）和索引（Index）分别存储在两个源操作数中，按分数从大到小排序，将排序后的分数与对应索引组成数据结构存储在目的操作数中。</li><li><code>asc_mrgsort4</code>、<code>asc_mrgsort4_sync</code>：将已经排好序的最多4条队列合并排列成1条队列，结果按照分数域由大到小排序。</li><li><code>asc_transpose</code>、<code>asc_transpose_sync</code>：实现16×16的二维矩阵数据块转置。</li><li><code>asc_transto5hd_b8</code>、<code>asc_transto5hd_b8_sync</code>、<code>asc_transto5hd_b16</code>、<code>asc_transto5hd_b16_sync</code>、<code>asc_transto5hd_b32</code>、<code>asc_transto5hd_b32_sync</code>：执行数据格式转换，一般用于将NCHW格式转换成NC1HWC0格式，也可用于二维矩阵数据块转置。</li><li><code>asc_set_va_reg</code>：用于设置<code>asc_transto5hd_b8</code>的地址，将操作数地址序列与地址寄存器关联。</li></ul><h3 id="数据搬运">数据搬运<a class="header-anchor" href="#数据搬运">​</a></h3><ul><li><code>asc_copy_gm2ub</code>、<code>asc_copy_gm2ub_sync</code>：将数据从Global Memory搬运到Unified Buffer（UB）。</li><li><code>asc_copy_ub2gm</code>、<code>asc_copy_ub2gm_sync</code>：将数据从UB搬运到Global Memory。</li><li><code>asc_copy_ub2ub</code>、<code>asc_copy_ub2ub_sync</code>：将数据从UB搬运到UB。</li><li><code>asc_copy_ub2l1</code>、<code>asc_copy_ub2l1_sync</code>：将数据从UB搬运到L1 Buffer。</li><li><code>asc_set_copy_pad_val</code>：与<code>asc_copy_gm2ub_align</code>配合使用，设置连续搬运数据块左右两侧需要填充的数据值。Ascend 950PR/Ascend 950DT支持<code>int8_t</code>、<code>uint8_t</code>、<code>int16_t</code>、<code>uint16_t</code>、<code>half</code>、<code>bfloat16_t</code>、<code>int32_t</code>、<code>uint32_t</code>、<code>float</code>。<code>fp4x2_e2m1_t</code>、<code>fp4x2_e1m2_t</code>、<code>hifloat8_t</code>、<code>fp8_e8m0_t</code>、<code>fp8_e5m2_t</code>、<code>fp8_e4m3fn_t</code>数据需要先转换为<code>int8_t</code>再传入。</li><li><code>asc_ndim_copy_dci</code>：执行N维搬运场景所需的数据缓存失效（Data Cache Invalidate，DCI）操作。</li><li><code>asc_copy_gm2l1</code>、<code>asc_copy_gm2l1_sync</code>：将数据从Global Memory搬运到L1 Buffer。</li><li><code>asc_copy_gm2l1_align</code>、<code>asc_copy_gm2l1_align_sync</code>：将Global Memory中的数据填充后搬运到L1 Buffer。</li><li><code>asc_copy_gm2l1_nd2nz</code>、<code>asc_copy_gm2l1_nd2nz_sync</code>：在Global Memory到L1 Buffer搬运过程中完成ND到NZ格式转换。</li><li><code>asc_copy_gm2l1_dn2nz</code>、<code>asc_copy_gm2l1_dn2nz_sync</code>：将矩阵数据从Global Memory搬运到L1 Buffer，并完成DN到NZ、NCHW到NC1HWC0或NCHW到C1HWNC0格式转换。D维未按C0大小对齐时，在L1 Buffer最内层维度填充0。</li><li><code>asc_copy_l12l0a</code>、<code>asc_copy_l12l0a_sync</code>、<code>asc_copy_l12l0b</code>、<code>asc_copy_l12l0b_sync</code>：将L1 Buffer中的512字节矩阵搬运到L0A Buffer或L0B Buffer，支持2D格式搬运、2D格式转置搬运、3D格式搬运。</li><li><code>asc_copy_l12l0b_trans</code>、<code>asc_copy_l12l0b_trans_sync</code>：将矩阵从L1 Buffer转置搬运到L0B Buffer。</li><li><code>asc_copy_l12l0b_mx</code>、<code>asc_copy_l12l0b_mx_sync</code>：将微缩放（Microscaling，MX）矩阵从L1 Buffer搬运到L0B Buffer。</li><li><code>asc_copy_l0c2gm</code>、<code>asc_copy_l0c2gm_sync</code>：将L0C Buffer中的数据搬运到Global Memory，支持量化、ReLU、Leaky ReLU、通道拆分和NZ2ND随路控制。</li><li><code>asc_copy_l0c2ub</code>、<code>asc_copy_l0c2ub_sync</code>：将L0C Buffer中的数据搬运到UB，支持量化、ReLU、Leaky ReLU和通道拆分随路控制。</li><li><code>asc_copy_l12fb</code>、<code>asc_copy_l12fb_sync</code>：将量化参数从L1 Buffer搬运到Fixpipe Buffer。</li><li><code>asc_copy_l12bt</code>、<code>asc_copy_l12bt_sync</code>：将矩阵乘使用的偏置（Bias）数据从L1 Buffer搬运到BiasTable Buffer。</li><li><code>asc_copy_l12ub</code>、<code>asc_copy_l12ub_sync</code>：将数据从L1 Buffer搬运到UB。</li><li><code>asc_fill_l1</code>、<code>asc_fill_l1_sync</code>：将<code>value</code>的二进制值赋值给目的操作数，对L1 Buffer的Local Memory进行初始化。</li><li><code>asc_set_l13d_fmatrix_b</code>：设置特征图属性描述，用于<code>asc_copy_l12l0a</code>、<code>asc_copy_l12l0b</code>的3D格式搬运接口配置填充值。从右矩阵获取特征图属性时使用该接口。</li><li><code>asc_set_l0c2gm_lrelu_alpha</code>：用于设置<code>asc_copy_l0c2l1</code>或<code>asc_copy_l0c2gm</code>计算过程中使用的Leaky ReLU alpha值，该值只支持<code>half</code>、<code>float</code>两种数据类型。</li><li><code>asc_set_l13d_padding</code>：设置填充属性描述，用于调用<code>asc_copy_l12l0a</code>时配置填充值。</li></ul><h3 id="标量操作">标量操作<a class="header-anchor" href="#标量操作">​</a></h3><ul><li><code>asc_clear_nthbit</code>、<code>asc_set_nthbit</code>：清除或设置<code>uint64_t</code>值中的指定比特位。</li><li><code>asc_atomic_add</code>、<code>asc_atomic_sub</code>、<code>asc_atomic_max</code>、<code>asc_atomic_min</code>、<code>asc_atomic_exch</code>、<code>asc_atomic_cas</code>：对Global Memory中的<code>int32_t</code>、<code>uint32_t</code>、<code>float</code>、<code>int64_t</code>、<code>uint64_t</code>数据执行标量原子操作，并返回操作前的值。</li><li><code>asc_atomic_and</code>、<code>asc_atomic_or</code>、<code>asc_atomic_xor</code>：对Global Memory中的<code>int32_t</code>、<code>uint32_t</code>、<code>int64_t</code>、<code>uint64_t</code>数据执行原子按位运算。</li><li><code>asc_atomic_inc</code>：对Global Memory中的<code>uint32_t</code>或<code>uint64_t</code>计数器执行原子递增操作；计数器数值大于等于<code>val</code>时赋值为0，否则加1。</li><li><code>asc_atomic_dec</code>：对Global Memory中的<code>uint32_t</code>或<code>uint64_t</code>计数器执行原子递减操作；计数器数值等于0或大于<code>val</code>时赋值为<code>val</code>，否则减1。</li></ul><h3 id="矩阵计算">矩阵计算<a class="header-anchor" href="#矩阵计算">​</a></h3><ul><li><code>asc_mmad</code>、<code>asc_mmad_sync</code>：完成矩阵乘加操作，支持<code>int8_t</code>、<code>hifloat8_t</code>、<code>fp8_e5m2_t</code>、<code>fp8_e4m3fn_t</code>、<code>half</code>、<code>bfloat16_t</code>、<code>float</code>同精度和混合精度输入组合。</li><li><code>asc_enable_fp8</code>：设置矩阵乘加计算开启FP8模式并关闭HiF8模式，L0A Buffer、L0B Buffer中的FP8数据在参与矩阵乘加计算之前不会转换为<code>hifloat8_t</code>数据。</li><li><code>asc_enable_hif8</code>：设置矩阵乘加计算开启HiF8模式，L0A Buffer、L0B Buffer中的8位数据在参与矩阵乘法运算前转换为<code>hifloat8_t</code>数据。</li><li><code>asc_enable_hf32_trans</code>：设置HF32模式舍入方式，使用该接口前需要先使用<code>asc_enable_hf32</code>开启HF32模式。</li><li><code>asc_enable_hf32</code>：设置矩阵乘加计算开启HF32模式，提升FP32数据的计算性能，但会带来一定的精度损失。</li><li><code>asc_set_fp32_mode</code>：设置矩阵乘加计算开启FP32模式，L0A Buffer、L0B Buffer中的FP32数据在参与矩阵乘加计算之前不做舍入处理。</li><li><code>asc_set_mmad_direction_m</code>、<code>asc_set_mmad_direction_n</code>：分别设置矩阵乘加计算优先通过M方向、N方向生成结果。</li></ul><h3 id="同步控制">同步控制<a class="header-anchor" href="#同步控制">​</a></h3><ul><li><code>asc_lock</code>、<code>asc_unlock</code>：用于AI Core内部异步流水线同步。</li><li><code>asc_sync_intra_arrive</code>、<code>asc_sync_intra_wait</code>：用于核间信号同步。</li><li><code>asc_sync_subblock_arrive</code>、<code>asc_sync_subblock_wait</code>：用于组内子块（Subblock）间的信号同步。</li><li><code>asc_sync_inter_arrive</code>、<code>asc_sync_inter_wait</code>：用于组间计算块（Block）的信号同步。</li><li><code>asc_sync_data_barrier</code>：等待指定范围内先前发起的内存访问完成。</li></ul><h3 id="系统变量">系统变量<a class="header-anchor" href="#系统变量">​</a></h3><ul><li><code>asc_get_smmu_tag_version</code>、<code>asc_get_phy_stack_base</code>、<code>asc_get_status</code>、<code>asc_get_sys_virtual_base</code>：分别获取系统内存管理单元（System Memory Management Unit，SMMU）版本信息、物理堆栈基地址、状态信息和系统虚拟基地址。</li><li><code>asc_get_block_idx</code>：获取当前运行核的索引。</li><li><code>asc_get_sub_block_num</code>：在分离模式下获取一个AI Core上的Cube Core或Vector Core数量。</li><li><code>asc_get_sub_block_id</code>：获取AI Core上的Vector Core ID。</li><li><code>asc_get_phy_buf_addr</code>：根据偏移量获取片上实际物理地址。</li><li><code>asc_get_core_id</code>、<code>asc_get_arch_ver</code>：分别获取核ID和架构版本。</li><li><code>asc_get_vf_len</code>：获取Tensor位宽VL（Vector Length）的大小。</li><li><code>asc_set_gm2l1_nz_para</code>：设置MTE2_NZ_PARA寄存器的值。</li><li><code>asc_set_l0c2gm_channel_para</code>：设置通道步长参数专用寄存器的比特位。</li><li><code>asc_set_l0c2gm_quant_post</code>：设置QUANT_POST寄存器的值。试验接口。</li><li><code>asc_set_l0c2gm_relu_alpha</code>：设置RELU_ALPHA寄存器的值。</li><li><code>asc_set_l12l0_padding_val</code>：设置PADDING_B寄存器的值。</li><li><code>asc_set_l3d_rpt_b</code>：用于设置<code>asc_copy_l12l0a</code>、<code>asc_copy_l12l0b</code>的2D格式搬运repeat参数。</li></ul><h3 id="缓存控制">缓存控制<a class="header-anchor" href="#缓存控制">​</a></h3><ul><li><code>asc_dci</code>：使整个数据缓存失效，不回写缓存行，未同步到主存的修改会被丢弃。调用前必须先执行<code>asc_sync_data_barrier(mem_dsb_t::DSB_ALL)</code>，等待此前的内存访问完成。</li></ul><h2 id="Bug修复">Bug修复<a class="header-anchor" href="#Bug修复">​</a></h2><ul><li><code>asc_sync_block_arrive</code>由9.0.0的<code>asc_sync_block_arrive(pipe, mode, flagID)</code>调整为<code>asc_sync_block_arrive(pipe, flag_id)</code>，删除<code>mode</code>参数并统一事件标号命名。</li><li><code>asc_sync_block_wait</code>由9.0.0的<code>asc_sync_block_wait(flagID)</code>调整为<code>asc_sync_block_wait(pipe, flag_id)</code>，新增流水线参数并统一事件标号命名。</li><li><code>asc_get_arch_ver</code>参数名由<code>coreVersion</code>统一为<code>core_version</code>。</li><li>修复<code>cache_ctrl.h</code>复用原子操作头文件保护宏的问题，避免包含顺序导致缓存控制声明被跳过。</li><li>统一<code>asc_simd.h</code>、<code>misc.h</code>、<code>cache_ctrl.h</code>、<code>sync.h</code>、<code>sys_var.h</code>和<code>utils_intf.h</code>中的头文件引用路径，避免安装目录变化导致包含失败。</li><li>将<code>asc_loadalign_postupdate</code>、<code>asc_loadalign_brc_postupdate</code>、<code>asc_loadalign_brc_postupdate_v2</code>、<code>asc_loadalign_brc_postupdate_v3</code>、<code>asc_loadalign_upsample_postupdate</code>、<code>asc_loadalign_downsample_postupdate</code>、<code>asc_loadalign_unpack_postupdate</code>、<code>asc_loadalign_unpack_postupdate_v2</code>、<code>asc_loadalign_deintlv_postupdate</code>中需要自动更新的UB源指针参数修正为指针引用，确保调用后地址变化对调用方可见。</li><li>将<code>asc_storealign_postupdate</code>、<code>asc_storealign_1st_postupdate</code>、<code>asc_storealign_pack_postupdate</code>、<code>asc_storealign_pack_postupdate_v2</code>中需要自动更新的UB目的指针参数修正为指针引用，确保调用后地址变化对调用方可见。</li><li>将不更新地址的<code>asc_storeunalign</code>目的参数由指针引用修正为普通指针，并补齐<code>asc_storeunalign_postupdate</code>的地址更新重载。</li><li>修复<code>half</code>转换为<code>int4b_t</code>接口的舍入模式命名。9.0.0将以下四种舍入模式的接口声明为向下舍入函数名，9.1.0修复为与实际舍入模式一致的函数名： <ul><li>向上舍入：<code>asc_half2int4x2_ru</code>、<code>asc_half2int4x2_ru_sat</code>、<code>asc_half2int4x2_ru_v2</code>、<code>asc_half2int4x2_ru_sat_v2</code>、<code>asc_half2int4x2_ru_v3</code>、<code>asc_half2int4x2_ru_sat_v3</code>、<code>asc_half2int4x2_ru_v4</code>、<code>asc_half2int4x2_ru_sat_v4</code>。</li><li>向零舍入：<code>asc_half2int4x2_rz</code>、<code>asc_half2int4x2_rz_sat</code>、<code>asc_half2int4x2_rz_v2</code>、<code>asc_half2int4x2_rz_sat_v2</code>、<code>asc_half2int4x2_rz_v3</code>、<code>asc_half2int4x2_rz_sat_v3</code>、<code>asc_half2int4x2_rz_v4</code>、<code>asc_half2int4x2_rz_sat_v4</code>。</li><li>最近偶数舍入：<code>asc_half2int4x2_rn</code>、<code>asc_half2int4x2_rn_sat</code>、<code>asc_half2int4x2_rn_v2</code>、<code>asc_half2int4x2_rn_sat_v2</code>、<code>asc_half2int4x2_rn_v3</code>、<code>asc_half2int4x2_rn_sat_v3</code>、<code>asc_half2int4x2_rn_v4</code>、<code>asc_half2int4x2_rn_sat_v4</code>。</li><li>最近远离零舍入：<code>asc_half2int4x2_rna</code>、<code>asc_half2int4x2_rna_sat</code>、<code>asc_half2int4x2_rna_v2</code>、<code>asc_half2int4x2_rna_sat_v2</code>、<code>asc_half2int4x2_rna_v3</code>、<code>asc_half2int4x2_rna_sat_v3</code>、<code>asc_half2int4x2_rna_v4</code>、<code>asc_half2int4x2_rna_sat_v4</code>。</li></ul></li><li>将<code>asc_int162half_rc</code>修正为<code>asc_int162half_rz</code>。</li><li>将<code>asc_reduce_min_datablock_</code>修正为<code>asc_reduce_min_datablock</code>，去除多余的尾部下划线。</li><li>将<code>asc_half2uint8_rd_sat_v2_impl</code>、<code>asc_half2uint8_rn_sat_v2_impl</code>、<code>asc_half2uint8_rna_sat_v2_impl</code>、<code>asc_half2uint8_ru_sat_v2_impl</code>、<code>asc_half2uint8_rz_sat_v2_impl</code>分别修正为<code>asc_half2uint8_rd_sat_v2</code>、<code>asc_half2uint8_rn_sat_v2</code>、<code>asc_half2uint8_rna_sat_v2</code>、<code>asc_half2uint8_ru_sat_v2</code>、<code>asc_half2uint8_rz_sat_v2</code>。</li><li>将以下<code>bfloat16_t</code>转换为<code>fp4x2_e1m2_t</code>接口的目的类型从<code>vector_f4e1m2x2</code>修正为<code>vector_fp4x2_e1m2_t</code>： <ul><li>向下舍入：<code>asc_bfloat162e1m2x2_rd</code>、<code>asc_bfloat162e1m2x2_rd_v2</code>、<code>asc_bfloat162e1m2x2_rd_v3</code>、<code>asc_bfloat162e1m2x2_rd_v4</code>。</li><li>最近偶数舍入：<code>asc_bfloat162e1m2x2_rn</code>、<code>asc_bfloat162e1m2x2_rn_v2</code>、<code>asc_bfloat162e1m2x2_rn_v3</code>、<code>asc_bfloat162e1m2x2_rn_v4</code>。</li><li>最近远离零舍入：<code>asc_bfloat162e1m2x2_rna</code>、<code>asc_bfloat162e1m2x2_rna_v2</code>、<code>asc_bfloat162e1m2x2_rna_v3</code>、<code>asc_bfloat162e1m2x2_rna_v4</code>。</li><li>向上舍入：<code>asc_bfloat162e1m2x2_ru</code>、<code>asc_bfloat162e1m2x2_ru_v2</code>、<code>asc_bfloat162e1m2x2_ru_v3</code>、<code>asc_bfloat162e1m2x2_ru_v4</code>。</li><li>向零舍入：<code>asc_bfloat162e1m2x2_rz</code>、<code>asc_bfloat162e1m2x2_rz_v2</code>、<code>asc_bfloat162e1m2x2_rz_v3</code>、<code>asc_bfloat162e1m2x2_rz_v4</code>。</li></ul></li><li>将<code>asc_half2uint8</code>和<code>asc_min_scalar</code>的非标准类型别名<code>vector_u8</code>、<code>vector_f16</code>修正为<code>vector_uint8_t</code>、<code>vector_half</code>。</li><li><code>asc_arange</code>、<code>asc_arange_descend</code>参数名由<code>index</code>统一为<code>value</code>。</li><li><code>asc_update_mask_b8</code>、<code>asc_update_mask_b16</code>、<code>asc_update_mask_b32</code>参数名由<code>scalar</code>统一为<code>value</code>。</li></ul><h2 id="增强">增强<a class="header-anchor" href="#增强">​</a></h2><ul><li><code>asc_copy_gm2ub_align</code>、<code>asc_copy_gm2ub_align_sync</code>、<code>asc_copy_ub2gm_align</code>、<code>asc_copy_ub2gm_align_sync</code>新增仅传入<code>dst</code>、<code>src</code>和<code>size</code>的简化重载。</li><li><code>asc_copy_l0c2l1</code>新增<code>asc_copy_l0c2l1_sync</code>，并新增<code>int16_t</code>目的数据与<code>int32_t</code>源数据、<code>bfloat16_t</code>目的数据与<code>float</code>源数据的组合，以及目的参数为<code>__cbuf__ void*</code>、源参数分别为<code>__cc__ int32_t*</code>或<code>__cc__ float*</code>的通用重载。</li><li><code>asc_copy_l12l0a_mx</code>新增<code>asc_copy_l12l0a_mx_sync</code>。</li><li><code>asc_set_atomic_add_int8</code>、<code>asc_set_atomic_add_int16</code>、<code>asc_set_atomic_add_int</code>：设置后续从UB、L0C Buffer到Global Memory的数据搬运开启原子累加，累加的数据类型分别为<code>int8_t</code>、<code>int16_t</code>、<code>int32_t</code>。</li><li><code>asc_gather</code>为<code>int16_t</code>、<code>uint16_t</code>、<code>half</code>、<code>bfloat16_t</code>数据新增使用<code>vector_uint32_t</code>索引的重载。</li><li><code>asc_gather_datablock</code>新增<code>int4b_t</code>重载和无需传入掩码参数的<code>uint64_t</code>重载。</li><li><code>asc_loadalign</code>、<code>asc_loadalign_brc</code>、<code>asc_loadalign_brc_v2</code>、<code>asc_loadalign_upsample</code>、<code>asc_loadalign_downsample</code>、<code>asc_loadalign_unpack</code>、<code>asc_loadalign_unpack_v2</code>、<code>asc_loadalign_deintlv</code>新增<code>int4b_t</code>、<code>vector_int4x2_t</code>重载。</li><li><code>asc_loadalign</code>、<code>asc_loadalign_upsample</code>、<code>asc_loadalign_downsample</code>、<code>asc_loadalign_postupdate</code>新增<code>vector_bool</code>重载。</li><li><code>asc_storealign</code>、<code>asc_storealign_1st</code>、<code>asc_storealign_intlv</code>、<code>asc_storeunalign</code>、<code>asc_storeunalign_postupdate</code>、<code>asc_storeunalign_post</code>、<code>asc_storeunalign_post_postupdate</code>、<code>asc_store</code>新增<code>int4b_t</code>、<code>vector_int4x2_t</code>数据重载。</li><li><code>asc_storealign</code>、<code>asc_storealign_pack</code>、<code>asc_storealign_postupdate</code>、<code>asc_storealign_pack_postupdate</code>、<code>asc_storeunalign_postupdate</code>新增<code>vector_bool</code>输出重载。</li><li><code>asc_scatter</code>新增9组目的UB地址在前、源矢量寄存器在后的重载，根据索引将源矢量寄存器元素分散写入UB。支持的数据类型为<code>int8_t</code>、<code>uint8_t</code>、<code>int16_t</code>、<code>uint16_t</code>、<code>half</code>、<code>bfloat16_t</code>、<code>int32_t</code>、<code>uint32_t</code>、<code>float</code>。</li><li><code>asc_create_iter_reg_b8</code>、<code>asc_create_iter_reg_b16</code>、<code>asc_create_iter_reg_b32</code>从单个偏移扩展为支持1至4个偏移。</li><li><code>asc_copy</code>新增将<code>vector_uint16_t</code>、<code>vector_uint32_t</code>矢量数据寄存器复制到<code>vector_bool</code>掩码寄存器的重载。</li><li><code>asc_duplicate_scalar</code>新增无需传入掩码参数的重载。</li></ul><h2 id="接口废弃">接口废弃<a class="header-anchor" href="#接口废弃">​</a></h2><p>本版本标记以下接口或特定重载为<code>deprecated</code>：</p><h3 id="数据搬运-1">数据搬运<a class="header-anchor" href="#数据搬运-1">​</a></h3><table><thead><tr><th align="left">废弃接口或重载</th><th align="left">替代接口</th><th align="left">说明</th></tr></thead><tbody><tr><td align="left"><code>asc_set_gm2ub_pad</code></td><td align="left"><code>asc_set_copy_pad_val</code></td><td align="left">使用通用搬运填充值配置接口。</td></tr><tr><td align="left"><code>asc_get_store_atomic_config</code>（Ascend 950PR/Ascend 950DT）</td><td align="left"><code>asc_atomic_add</code></td><td align="left">标量原子加无需预先配置和查询数据搬运原子状态。</td></tr><tr><td align="left"><code>asc_set_store_atomic_config_v2</code></td><td align="left"><code>asc_atomic_add</code></td><td align="left">标量原子加改为直接调用原子接口。</td></tr><tr><td align="left">源矢量寄存器在前、目的UB地址在后的<code>asc_scatter</code>重载</td><td align="left">目的UB地址在前、源矢量寄存器在后的<code>asc_scatter</code>重载</td><td align="left">支持的数据类型不变，仅调整参数顺序。</td></tr><tr><td align="left"><code>asc_exp_sub_v2(vector_float&amp;, vector_float, vector_float, vector_bool)</code></td><td align="left"><code>asc_exp_sub</code></td><td align="left"><code>half</code>输入的<code>asc_exp_sub_v2</code>仍保留，用于读取源操作数的奇数索引元素；仅<code>float</code>输入的该重载废弃。</td></tr></tbody></table><p><strong>注：</strong> 详情可参考<a href="../deprecated_interface.html">废弃接口</a>。</p></article></div>',1)])])}const p=e(a,[["render",l]]);export{u as __pageData,p as default};
